        } else {
          ctx.fillStyle = "#8B4513";
          ctx.fillRect(BTN_X, btnY, BTN_WIDTH, BTN_HEIGHT);
          ctx.fillStyle = "#FFF";
          ctx.font = "bold 14px monospace";
          ctx.fillText("🎈 AD FOR 60s NO GRAVITY", CANVAS_WIDTH / 2, btnY + 24);
        }
