import { WORLDS, getWorldForLevel } from "@/lib/config/worldConfig";
import { useEffect, useState } from "react";
import { useMobileDetect } from "@/lib/hooks/useMobileDetect";

interface LevelSelectProps {
  onSelectLevel: (level: number) => void;
  onBack: () => void;
}

export function LevelSelect({ onSelectLevel, onBack }: LevelSelectProps) {
  const worldOrder = ['forest', 'rocky', 'desert', 'ice', 'neon'];
  const { isMobile } = useMobileDetect();

  // Track viewport for responsive layout (with SSR-safe defaults)
  const [viewport, setViewport] = useState({ width: 800, height: 600 });
  const isLandscape = viewport.width > viewport.height;
  const isSmallHeight = viewport.height < 450;
  const isVerySmallHeight = viewport.height < 350;
  const isMobileLandscape = isMobile && isLandscape;

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const updateViewport = () => {
      const vp = window.visualViewport;
      setViewport({
        width: vp?.width ?? window.innerWidth,
        height: vp?.height ?? window.innerHeight
      });
    };

    updateViewport();
    window.addEventListener('resize', updateViewport);
    window.addEventListener('orientationchange', () => setTimeout(updateViewport, 100));
    window.visualViewport?.addEventListener('resize', updateViewport);

    return () => {
      window.removeEventListener('resize', updateViewport);
      window.removeEventListener('orientationchange', updateViewport);
      window.visualViewport?.removeEventListener('resize', updateViewport);
    };
  }, []);

  // Responsive grid columns - more columns on wider screens
  const getGridCols = () => {
    if (isVerySmallHeight) return 'grid-cols-10';
    if (isSmallHeight) return 'grid-cols-10';
    if (viewport.width < 400) return 'grid-cols-5';
    if (viewport.width < 600) return 'grid-cols-5';
    return 'grid-cols-10';
  };

  return (
    <div className="fixed inset-0 z-50 pointer-events-auto overflow-auto">
      <div 
        className="bg-black bg-opacity-95 min-h-full w-full flex flex-col items-center"
        style={{ 
          padding: isSmallHeight ? '8px 8px 16px' : '24px 16px',
        }}
      >
        <h1 className={`font-bold text-yellow-400 font-mono ${isSmallHeight ? 'text-xl mb-2' : 'text-4xl mb-4'}`}>
          SELECT LEVEL
        </h1>

        <button
          onClick={onBack}
          className={`text-gray-400 hover:text-white font-mono ${isSmallHeight ? 'text-xs mb-2' : 'text-sm mb-4'}`}
        >
          ← Back to Menu
        </button>

        <div className="w-full max-w-4xl px-2 md:px-4 space-y-3 md:space-y-6">
          {worldOrder.map((worldId) => {
            const world = WORLDS[worldId];
            const [startLevel, endLevel] = world.levelRange;
            const levels = [];
            for (let i = startLevel; i <= endLevel; i++) {
              levels.push(i);
            }

            return (
              <div 
                key={worldId} 
                className="bg-gray-900 rounded-lg"
                style={{ padding: isSmallHeight ? '8px' : '16px' }}
              >
                <div className={`flex items-center gap-2 ${isSmallHeight ? 'mb-1' : 'mb-3'}`}>
                  <div 
                    className={`rounded-full ${isSmallHeight ? 'w-3 h-3' : 'w-4 h-4'}`}
                    style={{ 
                      background: world.theme.pipeColor,
                      boxShadow: `0 0 10px ${world.theme.pipeColor}`
                    }}
                  />
                  <h2 
                    className={`font-bold font-mono ${isSmallHeight ? 'text-sm' : 'text-xl'}`} 
                    style={{ color: world.theme.pipeColor }}
                  >
                    {world.name}
                  </h2>
                  <span className={`text-gray-500 font-mono ${isSmallHeight ? 'text-xs' : 'text-sm'}`}>
                    L{startLevel}-{endLevel}
                  </span>
                </div>

                {!isVerySmallHeight && (
                  <p className={`text-gray-400 font-mono ${isSmallHeight ? 'text-xs mb-2' : 'text-sm mb-3'}`}>
                    {world.description}
                  </p>
                )}

                <div className={`grid ${getGridCols()} ${isSmallHeight ? 'gap-1' : 'gap-2'}`}>
                  {levels.map((level) => {
                    const isFirstOfWorld = level === startLevel;

                    return (
                      <button
                        key={level}
                        onClick={() => onSelectLevel(level)}
                        className={`
                          aspect-square rounded font-mono font-bold
                          transition-all duration-150 hover:scale-105 active:scale-95
                          ${isSmallHeight ? 'text-xs rounded-md' : 'text-sm rounded-lg'}
                          ${isFirstOfWorld 
                            ? 'bg-yellow-500 hover:bg-yellow-400 text-black ring-2 ring-yellow-300' 
                            : 'bg-gray-700 hover:bg-gray-600 text-white'
                          }
                        `}
                        title={`Level ${level} - ${world.name}`}
                      >
                        {level}
                      </button>
                    );
                  })}
                </div>

                {!isSmallHeight && (
                  <div className="mt-2 flex flex-wrap gap-1 md:gap-2 text-xs text-gray-500 font-mono">
                    {world.mechanics.hasMovingPipes && <span className="bg-gray-800 px-2 py-1 rounded">Moving</span>}
                    {world.mechanics.hasSlidingPipes && <span className="bg-gray-800 px-2 py-1 rounded">Sliding</span>}
                    {world.mechanics.hasRotatingObstacles && <span className="bg-gray-800 px-2 py-1 rounded">Rotating</span>}
                    {world.mechanics.hasFallingRocks && <span className="bg-gray-800 px-2 py-1 rounded">Falling</span>}
                    {world.mechanics.hasEnemies && <span className="bg-gray-800 px-2 py-1 rounded">Enemies</span>}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className={`text-gray-500 font-mono text-center ${isSmallHeight ? 'mt-2 text-xs' : 'mt-6 text-xs'}`}>
          50 Levels across 5 Worlds
        </div>
      </div>
    </div>
  );
}

client/src/components/TouchController.ts.content:
import React, { useEffect, useRef, useCallback, useState } from 'react';

interface TouchControllerProps {
  onFlap: () => void;
  onMoveUp: (active: boolean) => void;
  onMoveDown: (active: boolean) => void;
  onMoveLeft?: (active: boolean) => void;
  onMoveRight?: (active: boolean) => void;
  canvasWidth: number;
  canvasHeight: number;
  enabled: boolean;
  showControls: boolean;
}

export function TouchController({
  onFlap,
  onMoveUp,
  onMoveDown,
  onMoveLeft,
  onMoveRight,
  canvasWidth,
  canvasHeight,
  enabled,
  showControls,
}: TouchControllerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [activeButtons, setActiveButtons] = useState<Set<string>>(new Set());
  const [showTapFeedback, setShowTapFeedback] = useState(false);
  const [tapPosition, setTapPosition] = useState({ x: 0, y: 0 });
  const lastFlapTime = useRef(0);
  const controlsOpacity = useRef(1);
  const fadeTimeout = useRef<NodeJS.Timeout | null>(null);
  const activeTouch = useRef<Map<number, string>>(new Map());

  const FLAP_COOLDOWN = 100;
  const DPAD_SIZE = 140;
  const BUTTON_SIZE = 50;
  const DPAD_MARGIN = 20;
  const DPAD_X = canvasWidth - DPAD_SIZE - DPAD_MARGIN;
  const DPAD_Y = canvasHeight - DPAD_SIZE - DPAD_MARGIN - 40;
  const DPAD_CENTER_X = DPAD_X + DPAD_SIZE / 2;
  const DPAD_CENTER_Y = DPAD_Y + DPAD_SIZE / 2;

  const resetFadeTimer = useCallback(() => {
    controlsOpacity.current = 1;
    if (fadeTimeout.current) {
      clearTimeout(fadeTimeout.current);
    }
    fadeTimeout.current = setTimeout(() => {
      controlsOpacity.current = 0.6;
    }, 3000);
  }, []);

  const getButtonAt = (x: number, y: number): string | null => {
    const dx = x - DPAD_CENTER_X;
    const dy = y - DPAD_CENTER_Y;
    const upY = DPAD_CENTER_Y - BUTTON_SIZE - 5;
    const downY = DPAD_CENTER_Y + 5;
    const leftX = DPAD_CENTER_X - BUTTON_SIZE - 5;
    const rightX = DPAD_CENTER_X + 5;
    if (x >= DPAD_CENTER_X - BUTTON_SIZE / 2 && x <= DPAD_CENTER_X + BUTTON_SIZE / 2 &&
        y >= upY && y <= upY + BUTTON_SIZE) {
      return 'up';
    }
    if (x >= DPAD_CENTER_X - BUTTON_SIZE / 2 && x <= DPAD_CENTER_X + BUTTON_SIZE / 2 &&
        y >= downY && y <= downY + BUTTON_SIZE) {
      return 'down';
    }
    if (x >= leftX && x <= leftX + BUTTON_SIZE &&
        y >= DPAD_CENTER_Y - BUTTON_SIZE / 2 && y <= DPAD_CENTER_Y + BUTTON_SIZE / 2) {
      return 'left';
    }
    if (x >= rightX && x <= rightX + BUTTON_SIZE &&
        y >= DPAD_CENTER_Y - BUTTON_SIZE / 2 && y <= DPAD_CENTER_Y + BUTTON_SIZE / 2) {
      return 'right';
    }
    return null;
  };

  const activateButton = (button: string) => {
    setActiveButtons(prev => {
      const next = new Set(Array.from(prev));
      next.add(button);
      return next;
    });
    if (button === 'up') onMoveUp(true);
    if (button === 'down') onMoveDown(true);
    if (button === 'left' && onMoveLeft) onMoveLeft(true);
    if (button === 'right' && onMoveRight) onMoveRight(true);
  };

  const deactivateButton = (button: string) => {
    setActiveButtons(prev => {
      const next = new Set(Array.from(prev));
      next.delete(button);
      return next;
    });
    if (button === 'up') onMoveUp(false);
    if (button === 'down') onMoveDown(false);
    if (button === 'left' && onMoveLeft) onMoveLeft(false);
    if (button === 'right' && onMoveRight) onMoveRight(false);
  };

  const handleTouchStart = useCallback((e: TouchEvent) => {
    if (!enabled) return;
    e.preventDefault();
    resetFadeTimer();

    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;

    for (let i = 0; i < e.changedTouches.length; i++) {
      const touch = e.changedTouches[i];
      const x = (touch.clientX - rect.left) / rect.width * canvasWidth;
      const y = (touch.clientY - rect.top) / rect.height * canvasHeight;

      const button = getButtonAt(x, y);
      if (button) {
        activeTouch.current.set(touch.identifier, button);
        activateButton(button);
      } else {
        const now = Date.now();
        if (now - lastFlapTime.current > FLAP_COOLDOWN) {
          onFlap();
          lastFlapTime.current = now;
          setTapPosition({ x, y });
          setShowTapFeedback(true);
          setTimeout(() => setShowTapFeedback(false), 150);
        }
      }
    }
  }, [enabled, onFlap, canvasWidth, canvasHeight, resetFadeTimer]);

  const handleTouchMove = useCallback((e: TouchEvent) => {
    if (!enabled) return;
    e.preventDefault();

    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;

    for (let i = 0; i < e.changedTouches.length; i++) {
      const touch = e.changedTouches[i];
      const x = (touch.clientX - rect.left) / rect.width * canvasWidth;
      const y = (touch.clientY - rect.top) / rect.height * canvasHeight;

      const currentButton = activeTouch.current.get(touch.identifier);
      const newButton = getButtonAt(x, y);

      if (currentButton && currentButton !== newButton) {
        deactivateButton(currentButton);
        activeTouch.current.delete(touch.identifier);
      }
      if (newButton && newButton !== currentButton) {
        activeTouch.current.set(touch.identifier, newButton);
        activateButton(newButton);
      }
    }
  }, [enabled, canvasWidth, canvasHeight]);

  const handleTouchEnd = useCallback((e: TouchEvent) => {
    if (!enabled) return;

    for (let i = 0; i < e.changedTouches.length; i++) {
      const touch = e.changedTouches[i];
      const button = activeTouch.current.get(touch.identifier);
      if (button) {
        deactivateButton(button);
        activeTouch.current.delete(touch.identifier);
      }
    }
  }, [enabled]);

  // Cleanup function to deactivate all active buttons
  const deactivateAllButtons = useCallback(() => {
    activeTouch.current.forEach((button) => {
      if (button === 'up') onMoveUp(false);
      if (button === 'down') onMoveDown(false);
      if (button === 'left' && onMoveLeft) onMoveLeft(false);
      if (button === 'right' && onMoveRight) onMoveRight(false);
    });
    activeTouch.current.clear();
    setActiveButtons(new Set());
    console.log("[TOUCH DEBUG] Deactivated all buttons");
  }, [onMoveUp, onMoveDown, onMoveLeft, onMoveRight]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const options: AddEventListenerOptions = { passive: false };

    container.addEventListener('touchstart', handleTouchStart, options);
    container.addEventListener('touchmove', handleTouchMove, options);
    container.addEventListener('touchend', handleTouchEnd, options);
    container.addEventListener('touchcancel', handleTouchEnd, options);

    // Also add window-level listeners as safety net for touches that end outside container
    window.addEventListener('touchend', handleTouchEnd, options);
    window.addEventListener('touchcancel', handleTouchEnd, options);

    return () => {
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);
      container.removeEventListener('touchend', handleTouchEnd);
      container.removeEventListener('touchcancel', handleTouchEnd);
      window.removeEventListener('touchend', handleTouchEnd);
      window.removeEventListener('touchcancel', handleTouchEnd);
      // Deactivate all buttons when unmounting
      deactivateAllButtons();
    };
  }, [handleTouchStart, handleTouchMove, handleTouchEnd, deactivateAllButtons]);

  // Also deactivate all buttons when enabled changes to false
  useEffect(() => {
    if (!enabled) {
      deactivateAllButtons();
    }
  }, [enabled, deactivateAllButtons]);

  useEffect(() => {
    return () => {
      if (fadeTimeout.current) {
        clearTimeout(fadeTimeout.current);
      }
    };
  }, []);

  if (!showControls) return null;

  const upY = DPAD_CENTER_Y - BUTTON_SIZE - 5;
  const downY = DPAD_CENTER_Y + 5;
  const leftX = DPAD_CENTER_X - BUTTON_SIZE - 5;
  const rightX = DPAD_CENTER_X + 5;

  return (
    <div
      ref={containerRef}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: `${canvasWidth}px`,
        height: `${canvasHeight}px`,
        touchAction: 'none',
        userSelect: 'none',
        WebkitUserSelect: 'none',
        pointerEvents: enabled ? 'auto' : 'none',
        zIndex: 1000,
      }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${canvasWidth} ${canvasHeight}`}
        preserveAspectRatio="none"
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          pointerEvents: 'none',
        }}
      >
        <defs>
          <linearGradient id="buttonGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="rgba(255,255,255,0.4)" />
            <stop offset="100%" stopColor="rgba(255,255,255,0.1)" />
          </linearGradient>
          <linearGradient id="activeButtonGradient" x1="0%" y1="0%" x2="0%" y2="100%">
